          "plainKo": "AI와는 상관없이, 헬스케어 회사들이 2분기에 시장 예상을 크게 뛰어넘는 실적을 내고 올해 전망치까지 함께 올렸습니다. 예상치를 몇 배로 넘긴 이익과 상향된 가이던스가 겹치자 증권사들이 목표주가를 한꺼번에 올리며 주가가 뛰었습니다.",
